static int xact_heap_ptr_ok(uint32_t p) { return p >= 0x10000u && p < 0x08000000u && !(p & 3u); }
static int xact_heap_less(uint32_t a, uint32_t b)          /* a due before b (signed hi, unsigned lo) */
{
    int32_t ah = (int32_t)MEM32(a + 0x1C), bh = (int32_t)MEM32(b + 0x1C);
    if (ah != bh) return ah < bh;
    return MEM32(a + 0x18) < MEM32(b + 0x18);
}
static void xact_heap_sanitize(uint32_t heap)
{
    if (!xact_heap_ptr_ok(heap)) return;
    uint32_t arr = MEM32(heap), cap = MEM32(heap + 4), n = MEM32(heap + 8);
    if (!n) return;
    if (!xact_heap_ptr_ok(arr) || cap > 0x10000u || n > cap) {
        fprintf(stderr, "[XACT-HEAP] heap=%08X arr=%08X cap=%u count=%u: reset\n", heap, arr, cap, n);
        MEM32(heap + 8) = 0; return;
    }
    uint32_t k = 0, bad = 0, first = 0;
    for (uint32_t i = 0; i < n; i++) {
        uint32_t e = MEM32(arr + i * 4);
        if (xact_heap_ptr_ok(e)) MEM32(arr + k++ * 4) = e;
        else if (!bad++) first = e;
    }
    if (!bad) return;
    MEM32(heap + 8) = k;
    for (uint32_t i = k; i-- > 0;) {                          /* heapify (1-based min-heap) */
        uint32_t j = i;
        for (;;) {
            uint32_t l = 2 * j + 1, r = l + 1, m = j;
            if (l < k && xact_heap_less(MEM32(arr + l * 4), MEM32(arr + m * 4))) m = l;
            if (r < k && xact_heap_less(MEM32(arr + r * 4), MEM32(arr + m * 4))) m = r;
            if (m == j) break;
            uint32_t t = MEM32(arr + j * 4); MEM32(arr + j * 4) = MEM32(arr + m * 4); MEM32(arr + m * 4) = t;
            j = m;
        }
    }
    for (uint32_t i = 0; i < k; i++) MEM16(MEM32(arr + i * 4) + 8) = (uint16_t)(i + 1);
    fprintf(stderr, "[XACT-HEAP] heap=%08X dropped %u bad entr%s (first %08X), %u kept\n", heap, bad, bad == 1 ? "y" : "ies", first, k);
}

